"use client";

import dynamic from "next/dynamic";
import type { Lang } from "@/lib/problems/starters";

const MonacoEditor = dynamic(
  () => import("@monaco-editor/react").then((m) => m.default),
  { ssr: false, loading: () => <EditorFallback /> },
);

interface Props {
  value: string;
  language: Lang;
  theme: "vs-dark" | "light" | "hc-black";
  fontSize: number;
  onChange: (value: string) => void;
  height?: string | number;
}

/**
 * Thin Monaco wrapper. Kept separate so any page can consume it and so we
 * can swap the underlying editor without touching consumers.
 */
export function CodeEditor({
  value,
  language,
  theme,
  fontSize,
  onChange,
  height = "100%",
}: Props) {
  return (
    <div className="h-full w-full overflow-hidden rounded-xl bg-neutral-950 ring-1 ring-neutral-200/70">
      <MonacoEditor
        height={height}
        theme={theme}
        language={language}
        value={value}
        onChange={(next) => onChange(next ?? "")}
        options={{
          fontSize,
          minimap: { enabled: false },
          scrollBeyondLastLine: false,
          smoothScrolling: true,
          padding: { top: 12, bottom: 12 },
          renderLineHighlight: "none",
          scrollbar: { verticalScrollbarSize: 8, horizontalScrollbarSize: 8 },
          fontLigatures: true,
          wordWrap: "on",
        }}
      />
    </div>
  );
}

function EditorFallback() {
  return (
    <div className="grid h-full place-items-center bg-neutral-950 text-[12px] text-neutral-500">
      Loading editor…
    </div>
  );
}
